ng><br><?=h($r['address'])?><br><?=h($r['town'])?></td><td><?=h($r['why_now'])?></td><td><strong><?=h($r['recommended_action'])?></strong><br><br><small><?=h($r['compliance_note'])?></small></td><td><strong>Content:</strong> <?=h($r['content_angle'])?><br><br><strong>Ad:</strong> <?=h($r['ad_angle'])?><br><br><strong>Follow-up:</strong> <?=h($r['followup_angle'])?></td></tr><?php endforeach;?></table></section></main><?php goliath_ui_close(); ?></body></html>